function fetch_url($u) {
    if (function_exists('curl_init')) {
        $c = curl_init($u);
        curl_setopt_array($c, [CURLOPT_RETURNTRANSFER => true, CURLOPT_FOLLOWLOCATION => true, CURLOPT_TIMEOUT => 15, CURLOPT_CONNECTTIMEOUT => 8, CURLOPT_USERAGENT => 'Mozilla/5.0 gta-id-yukla']);
        $d = curl_exec($c); $code = curl_getinfo($c, CURLINFO_HTTP_CODE); curl_close($c);
        return ($d !== false && $code == 200) ? $d : false;
    }
    $ctx = stream_context_create(['http' => ['timeout' => 15, 'header' => "User-Agent: Mozilla/5.0 gta-id-yukla\r\n"]]);
    $d = @file_get_contents($u, false, $ctx);
    return $d === false ? false : $d;
}
function is_image($d) {
    return strlen($d) > 100 && (substr($d, 0, 8) === "\x89PNG\r\n\x1a\n" || substr($d, 0, 3) === "\xFF\xD8\xFF" || substr($d, 0, 3) === 'GIF');
}

if (isset($_GET['step'])) {
    header('Content-Type: application/json; charset=utf-8');
    $t0 = time(); $ok = 0; $fail = []; $left = 0;
    foreach ($LIST as $rel) {
        $f = $DIR . $rel;
        if (is_file($f) && filesize($f) > 100) continue;
        if (time() - $t0 > 20) { $left++; continue; }
        $d = fetch_url($BASE . $rel);
        if ($d === false || !is_image($d)) { $fail[] = $rel; continue; }
        if (!is_dir(dirname($f))) @mkdir(dirname($f), 0755, true);
        if (@file_put_contents($f . '.tmp', $d) === false) { echo json_encode(['error' => 'gta-id/ papkasiga yozib bo\'lmadi — papkaga yozish huquqini (chmod 755/775) tekshiring.']); exit; }
        rename($f . '.tmp', $f); $ok++;
    }
    $have = 0; foreach ($LIST as $rel) if (is_file($DIR . $rel) && filesize($DIR . $rel) > 100) $have++;
    echo json_encode(['ok' => $ok, 'fail' => $fail, 'left' => $left, 'have' => $have, 'total' => count($LIST)]);
    exit;
}
