<p>open.mp dagi <b><?= count($LIST) ?></b> ta rasm shu serverning <code>gta-id/</code> papkasiga saqlanadi. Bir marta bajariladi, keyin sahifa rasmlarni saytning o'zidan oladi.</p>
<button id="go">YUKLASHNI BOSHLASH</button>
<div class="bar"><i id="b"></i></div><div id="m"></div>
<form method="post" style="margin-top:22px" onsubmit="return confirm('Skript o\'chirilsinmi?')"><button class="s" name="del" value="1">Skriptni o'chirish (tugagach)</button></form>
<script>
const m=document.getElementById('m'),b=document.getElementById('b');let run=false;
async function step(){let tries=0;for(;;){let j;try{const r=await fetch('?step=1&t='+Date.now());j=await r.json()}catch(e){if(++tries>3){m.textContent='Xato: serverdan javob kelmadi.';break}continue}
 if(j.error){m.textContent=j.error;break}
 b.style.width=(j.have/j.total*100)+'%';m.textContent=j.have+' / '+j.total+' rasm saqlandi'+(j.fail.length?'\nOlinmadi: '+j.fail.length+' ta (masalan '+j.fail[0]+')':'');
 if(!j.left){m.textContent+=j.fail.length&&j.have===0?'\nServer open.mp ga ulana olmayapti (tashqi ulanish yopiq bo\'lishi mumkin).':'\nTayyor.';break}}
 run=false;document.getElementById('go').disabled=false}
document.getElementById('go').onclick=()=>{if(run)return;run=true;document.getElementById('go').disabled=true;m.textContent='Boshlandi…';step()};
</script></main></body></html>
